package com.noop.oura

import java.util.Locale
import org.junit.Assert.assertEquals
import org.junit.Test

// Generated by swiftc -O Sources/OuraProtocol/*.swift main.swift; stdout is verbatim, never
// calculated from Kotlin expectations. The symmetric Swift regression pins the other direction.
class OuraRawOracleTest {
    @Test fun exhaustiveQualityAndExtremeRecordsMatchStandaloneSwiftStdout() {
        var checksum = 14695981039346656037UL
        var total = 0
        for (a in 0..255) for (b in 0..255) {
            val fields = OuraRawInstruments.recordFields(OuraRecord(0x80, 1, intArrayOf(a, b)))
            for (key in listOf("ibi", "quality")) {
                val value = fields.first { it.key == key }.values[0].toInt()
                checksum = (checksum xor value.toULong()) * 1099511628211UL
                total += value
            }
        }
        val cases = listOf(
            0x80 to emptyList(), 0x80 to listOf(0, 0, 100, 8, 255, 31, 123),
            0x60 to List(14) { 0 }, 0x60 to List(14) { 255 }, 0x60 to (1..13).toList(),
            0x46 to listOf(0, 128, 255, 127), 0x46 to listOf(0),
            0x47 to listOf(255, 128, 127, 255, 0, 63), 0x47 to listOf(1, 2, 3, 4, 64),
            0x5d to listOf(0, 0, 255, 255), 0x5d to listOf(99),
            0x81 to listOf(128, 255, 255, 255), 0x8b to listOf(1, 2, 3, 4, 5), 0x90 to listOf(0, 255))
        val lines = mutableListOf("quality-exhaustive sum=$total fnv=${checksum.toString(16)}")
        for ((tag, body) in cases) {
            val fields = OuraRawInstruments.recordFields(OuraRecord(tag, 1, body.toIntArray()))
            val typed = fields.filter { !it.key.startsWith("byte[") }.joinToString(";") { field ->
                field.key + "=" + field.values.joinToString(",") { String.format(Locale.ROOT, "%.4f", it) }
            }
            lines.add("%02x".format(tag) + "[${body.size}] typed=$typed rawFields=${fields.count { it.key.startsWith("byte[") }}")
        }
        val stats = OuraRawInstruments.statistics(listOf(-327.68, 0.0, 327.67))!!
        lines.add(String.format(Locale.ROOT, "stats %.4f %.4f %.4f %.4f %d", stats.latest, stats.minimum, stats.maximum, stats.mean, stats.count))
        val memory = OuraRawBuffer(maxRecords = 2, maxBytes = 20, maxValues = 40)
        repeat(4) { memory.append(OuraRawInstruments.capture(listOf(0x80, 6, 1, 0, 0, 0, 100, 8))[0], it.toLong()) }
        val snap = memory.snapshot()
        lines.add("window ${snap.records.size} ${snap.evictedRecords} ${snap.evictedBytes} ${snap.evictedValues} ${snap.truncatedRecords}")
        lines.add("catalog " + OuraRawInstruments.catalog.joinToString(" ") { "${it.key}:${it.acquisition}:${if (it.verified) 1 else 0}:${if (it.supported) 1 else 0}" })
        assertEquals("""
quality-exhaustive sum=67174400 fnv=389e3b7cec6a9325
80[0] typed= rawFields=0
80[7] typed=ibi=0.0000,800.0000,2047.0000;quality=0.0000,1.0000,3.0000 rawFields=7
60[14] typed=ibi=0.0000,0.0000,0.0000,0.0000,0.0000,0.0000;amplitude=0.0000,0.0000,0.0000,0.0000,0.0000,0.0000 rawFields=14
60[14] typed=ibi=2047.0000,2047.0000,2047.0000,2047.0000,2047.0000,2047.0000;amplitude=8323072.0000,8323072.0000,8323072.0000,8323072.0000,8323072.0000,8323072.0000 rawFields=14
60[13] typed= rawFields=13
46[4] typed=temperature=-327.6800,327.6700 rawFields=4
46[1] typed= rawFields=1
47[6] typed=x=-1024.0000;y=1016.0000;z=-8.0000;motion=31.0000 rawFields=6
47[5] typed= rawFields=5
5d[4] typed=hr=0.0000,255.0000;rmssd=0.0000,255.0000 rawFields=4
5d[1] typed= rawFields=1
81[4] typed= rawFields=4
8b[5] typed= rawFields=5
90[2] typed= rawFields=2
stats 327.6700 -327.6800 327.6700 -0.0033 3
window 2 2 16 8 0
catalog event:41:record:0:0 event:42:record:0:0 event:43:record:0:0 event:45:record:0:0 event:53:record:0:0 event:85:record:0:0 event:60:record:1:1 event:71:record:0:1 event:6e:record:0:1 event:80:record:1:1 event:44:record:1:1 event:5d:record:1:1 event:6f:record:0:1 event:7b:record:0:1 event:77:record:0:1 event:46:record:1:1 event:69:record:1:1 event:75:record:1:1 event:47:record:1:1 event:6b:record:0:1 event:49:record:0:1 event:4c:record:0:1 event:4f:record:0:1 event:57:record:0:1 event:58:record:0:1 event:6a:record:0:1 event:4b:record:0:1 event:4e:record:0:1 event:5a:record:0:1 event:50:record:0:1 event:51:record:0:1 event:52:record:0:1 event:7e:record:0:1 event:7f:record:0:1 event:70:record:0:1 event:8b:record:0:1 event:81:record:0:1 hr:push:1:1 motion:push:1:1 battery:poll:1:1 status:02:poll:1:1 status:04:poll:1:1 status:0b:poll:1:1
""".trimIndent(), lines.joinToString("\n"))
    }
}
